def _phrase_rules(src_file, phrases):
    """Rules for quoted questionnaire strings. Every phrase must occur in the source."""
    src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'public', src_file), encoding='utf-8').read()
    rules, done = [], set()
    for nl, en in phrases:
        if nl in done:
            continue
        done.add(nl)
        found = False
        for q in ("'", '"'):
            nl_q = q + (nl.replace("'", "\\'") if q == "'" else nl) + q
            if nl_q in src:
                en_q = q + (en.replace("'", "\\'") if q == "'" else en.replace('"', '\\"')) + q
                rules.append((nl_q, en_q))
                found = True
        if not found:
            raise ValueError('phrase not found in ' + src_file + ': ' + nl)
    return rules

