 ('<label>Soort situatie</label>', '<label>Type of situation</label>'),
 ('<div class="status-box" style="text-align:left;margin:0">${session.category}</div>', '<div class="status-box" style="text-align:left;margin:0">${catLabel(session.category)}</div>'),
 ('De andere deelnemer heeft al ingediend, de categorie kan nu niet meer gewijzigd worden.', 'The other participant has already submitted, the category can no longer be changed.'),
